"use strict";

import "./popup.css";

(function () {
  chrome.storage.local.get(
    ["sheetURL", "userSignedIn", "urlData", "scrapingStatus"],
    function (lresult) {
      if (lresult.scrapingStatus === true) {
        showScraping();
      }
      //check if user has logged in and to show sign in or sign out,
      if (lresult.userSignedIn == true) {
        var element = document.getElementById("googleSignIn");
        element.innerHTML = element.innerHTML.replace(
          "Sign in with Google",
          "Sign out"
        );
      } else {
        document.getElementById("goToSheet").style.display = "none";
        document.getElementById("loadFromSheet").style.display = "none";
      }

      try {
        var x = Object.keys(lresult.urlData).length;
        if (x < 1 || x === undefined) {
          document.getElementById("startscrape").style.display = "none";
          document.getElementById("customTimeDiv").style.display = "none";
        }
        else {
          document.getElementById("loadFromSheet").style.display = "none";
        }
      } catch (e) {
        //its ok continue;
        document.getElementById("startscrape").style.display = "none";
        document.getElementById("customTimeDiv").style.display = "none";
      }

      //listen to gotosheet button
      document.getElementById("goToSheet").addEventListener("click", (e) => {
        chrome.runtime.sendMessage({ method: "goToGoogleSheet" });
        window.close();
      });

      //listen to load from sheet button
      document
        .getElementById("loadFromSheet")
        .addEventListener("click", (e) => {
          chrome.runtime.sendMessage({ method: "loadFromSheet" });

          alert(
            "You should see Start Scraping button, if data is loaded successfully."
          );
          window.close();
        });

      //listen to scrape button
      document.getElementById("startscrape").addEventListener("click", (e) => {
        chrome.runtime.sendMessage({ method: "start_scraping" }, function () {
          console.log("scrapping or finished");
        });

        showScraping();
        // window.reload();
        // window.close();
      });

      //listen to google sign in button and then sign the user in
      document.getElementById("googleSignIn").addEventListener("click", (e) => {
        //sign in from background, obviously
        var el = document.getElementById("googleSignIn");

        if (el.innerText.includes("Sign out")) {
          chrome.runtime.sendMessage({ method: "googleSignOut" });
        } else {
          chrome.runtime.sendMessage({ method: "googleSignIn" }, function () {
            window.location.reload();
          });
        }
        window.location.reload();
      });

      //event listenr for timer button, which reads time and validates the input string
      document
        .getElementById("customTimeButton")
        .addEventListener("click", timeEntered);

      //ensuring that the string is in required format
      function timeEntered() {
        var customTimeInput = document.getElementById("customTime").value;
        // alert(isNaN(customTimeInput));
        if (!isNaN(customTimeInput) && customTimeInput > 1999) {
          var customTimeNumber = +customTimeInput;
          if (customTimeNumber != NaN) {
            //the number is valid, go ahead with changing its suspension number;
            chrome.runtime.sendMessage({
              method: "change_timer",
              data: customTimeNumber,
            });
            alert("custom timer is set");
          }
        } else {
          alert("Enter a valid milliseconds");
        }
      }
    }
  );

  function showScraping() {
    document.getElementById("startscrape").style.display = "none";
    document.getElementById("customTimeDiv").style.display = "none";
    document.getElementById("goToSheet").style.display = "none";
    document.getElementById("loadFromSheet").style.display = "none";
    document.getElementById("googleSignInDiv").style.display = "none";
    const loadingMessage = document.createElement("div");
    loadingMessage.id = "loadingMessage";
    loadingMessage.style.textAlign = "center";
    loadingMessage.style.marginTop = "20px";
    loadingMessage.style.display = "flex";
    loadingMessage.style.flexDirection = "column";
    loadingMessage.style.alignItems = "center";
    loadingMessage.style.justifyContent = "center";
    loadingMessage.innerHTML = `
      <div style="font-size: 16px; color: #333; margin-bottom: 10px; font-weight: bold;">
        Scraping in progress, please come back in sometime...
      </div>
      <div class="spinner"></div>
      <style>
        .spinner {
          border: 4px solid #f3f3f3;
          border-top: 4px solid #007bff;
          border-radius: 50%;
          width: 40px;
          height: 40px;
          animation: spin 1s linear infinite;
        }
    
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
      </style>
    `;
    document.getElementById("mainApp").append(loadingMessage);
    document.querySelector(".divider").style.display = "none"
  }
})();
